<?php
require_once __DIR__.'/../config/db.php';require_once __DIR__.'/../services/requestService.php';require_once __DIR__.'/../includes/auth.php';if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('POST required');}verifyCsrfToken($_POST);$pdo=openDatabase();$user=requireLogin($pdo);requireRole($user,['Student','Administrator']);$id=filter_input(INPUT_POST,'request_id',FILTER_VALIDATE_INT);if(!$id||$id<1){http_response_code(400);exit('Invalid ID');}
try{[$errors,$data]=validateSubmission(array_merge($_POST,['student_name'=>$user['full_name'],'student_email'=>$user['email']]));if($errors)throw new InvalidArgumentException(implode(' ',$errors));$ok=updateOpenRequestForUser($pdo,$id,$user,$data);if(!$ok){http_response_code(404);exit('Request not found.');}header('Location: /php/request-details.php?request_id='.$id,true,303);exit;}catch(InvalidArgumentException $e){http_response_code(422);exit(escapeHtml($e->getMessage()));}catch(Throwable $e){error_log($e->getMessage());http_response_code(500);exit('Unable to update request');}
